64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Dedicated audit logger. A successful owner create emits a single line here carrying the new
73	     * owner's id, customer code, registration date and membership level, so the create side-effect
74	     * can be audited independently of the application log.
75	     */
76	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    /**
87	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
88	     * and a domain containing at least one dot, with no whitespace in any segment.
89	     */
90	    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
91	
92	    /**
93	     * Required national-number length per E.164 country code. A normalized telephone whose country
94	     * code appears here must carry exactly this many national digits after the code; Australia
95	     * ({@code +61}) requires 9 and the North American Numbering Plan ({@code +1}) requires 10.
96	     * Country codes not listed are only subject to the generic 8-to-15 total-digit rule.
97	     */
98	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTH = Map.of("61", 9, "1", 10);
99	
100	    /**
101	     * Maximum number of owners permitted in a single city. A create whose city already holds this many
102	     * owners (compared case-insensitively) is rejected with a 409 Conflict.
103	     */
104	    private static final int MAX_OWNERS_PER_CITY = 50;
105	
106	    /**
107	     * Maximum number of owners that may be registered on a single day (by registration date). A create
108	     * attempted once this many owners already carry today's registration date is rejected with a
109	     * 429 Too Many Requests.
110	     */
111	    private static final int MAX_OWNERS_PER_DAY = 100;
112	
113	    /**
114	     * Threshold above which a create is flagged with a bulk-signup warning. When more than this many
115	     * owners already carry the new owner's registration date, the created owner is flagged
116	     * ({@code bulkSignupWarning} true); otherwise the flag is false.
117	     */
118	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
119	
120	    /**
121	     * Expansions of the common street-type abbreviations recognised by {@link #normalizeAddress}.
122	     * Keys and values are upper-case, matching the casing the address is folded to before expansion.
123	     */
124	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
125	        "ST", "STREET",
126	        "RD", "ROAD",
127	        "AVE", "AVENUE");
128	
129	    /**
130	     * Inclusive 4-digit postcode range permitted per region, keyed by the region derived from the
131	     * owner's city ({@link Owner#getLocality()}): NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. A
132	     * region not listed (the {@code 'UNKNOWN'} locality of a city with no known region) accepts any
133	     * 4-digit postcode.
134	     */
135	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
136	        "NSW", new int[] {2000, 2099},
137	        "VIC", new int[] {3000, 3099},
138	        "QLD", new int[] {4000, 4099});
139	
140	    public OwnerRestControllerV1(ClinicService clinicService,
141	                                 OwnerMapper ownerMapper,
142	                                 PetMapper petMapper,
143	                                 VisitMapper visitMapper) {
144	        this.clinicService = clinicService;
145	        this.ownerMapper = ownerMapper;
146	        this.petMapper = petMapper;
147	        this.visitMapper = visitMapper;
148	    }
149	
150	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
151	    @Override
152	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
153	        Collection<Owner> owners;
154	        if (lastName != null) {
155	            owners = this.clinicService.findOwnerByLastName(lastName);
156	        } else {
157	            owners = this.clinicService.findAllOwners();
158	        }
159	        if (owners.isEmpty()) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
178	        validateRequiredFields(ownerFieldsDto);
179	        HttpHeaders headers = new HttpHeaders();
180	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
181	        LocalDate registrationDate = Owner.resolveRegistrationDate(owner.getRegistrationDate());
182	        owner.setRegistrationDate(registrationDate);
183	        requireDailyCapacity(registrationDate);
184	        requireCityHasCapacity(owner.getCity());
185	        validatePostcode(owner);
186	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
187	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
188	            joinHousehold(owner);
189	        }
190	        owner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
191	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
192	        requireUniqueIdentity(owner);
193	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
194	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
195	        owner.setBulkSignupWarning(countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
196	        this.clinicService.saveOwner(owner);
197	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
198	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel());
199	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
200	        headers.setLocation(UriComponentsBuilder.newInstance()
201	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
202	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
203	    }
204	
205	    /**
206	     * Rejects a create once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the new owner's
207	     * adjusted business-day registration date. Existing owners are counted by {@code registrationDate}
208	     * equal to that date, before the new owner is saved, so the count reflects only the owners that
209	     * existed prior to this create.
210	     *
211	     * @param registrationDate the new owner's effective registration date, already rolled forward onto
212	     *     a business day
213	     * @throws DailyOwnerLimitException if {@value #MAX_OWNERS_PER_DAY} or more owners are already
214	     *     registered on that business day
215	     */
216	    private void requireDailyCapacity(LocalDate registrationDate) {
217	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
218	            throw new DailyOwnerLimitException(registrationDate);
219	        }
220	    }
221	
222	    /**
223	     * Counts the existing owners whose registration date equals the given business-day date. This is
224	     * evaluated before the new owner is saved, so it reflects only the owners that existed prior to
225	     * this create. It is the single definition of the per-day count shared by the daily-limit rule and
226	     * the bulk-signup warning.
227	     *
228	     * @param registrationDate the effective business-day registration date to count against
229	     * @return the number of pre-existing owners registered on that date
230	     */
231	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
232	        return this.clinicService.findAllOwners().stream()
233	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
234	            .count();
235	    }
236	
237	    /**
238	     * Rejects an owner whose city already contains the maximum allowed number of owners
239	     * ({@value #MAX_OWNERS_PER_CITY}). Existing owners are counted by city compared case-insensitively,
240	     * before the new owner is saved, so the count reflects only the owners that existed prior to this
241	     * create.
242	     *
243	     * @param city the city of the owner being created
244	     * @throws CityOwnerLimitException if the city already holds {@value #MAX_OWNERS_PER_CITY} or more owners
245	     */
246	    private void requireCityHasCapacity(String city) {
247	        long cityOwnerCount = this.clinicService.findAllOwners().stream()
248	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
249	            .count();
250	        if (cityOwnerCount >= MAX_OWNERS_PER_CITY) {
251	            throw new CityOwnerLimitException(city);
252	        }
253	    }
254	
255	    /**
256	     * Validates a supplied postcode against the owner's region. Postcode is optional: an owner with no
257	     * postcode is accepted unchanged. When present it is a 4-digit string (enforced by the request
258	     * schema) that must fall within the inclusive range permitted for the region derived from the
259	     * owner's city ({@link #REGION_POSTCODE_RANGES}); a city whose region is unknown accepts any 4-digit
260	     * postcode. An out-of-range postcode is rejected with a 400 Bad Request.
261	     *
262	     * @param owner the owner being created, with its city and postcode set
263	     * @throws InvalidOwnerFieldsException if a supplied postcode is out of range for the city's region
264	     */
265	    private void validatePostcode(Owner owner) {
266	        String postcode = owner.getPostcode();
267	        if (postcode == null) {
268	            return;
269	        }
270	        int[] range = REGION_POSTCODE_RANGES.get(owner.getLocality());
271	        if (range == null) {
272	            return;
273	        }
274	        int value = Integer.parseInt(postcode);
275	        if (value < range[0] || value > range[1]) {
276	            throw new InvalidOwnerFieldsException(List.of("postcode"));
277	        }
278	    }
279	
280	    /**
281	     * Generates the customer code for a newly created owner, formatted
282	     * {@code '<CITY3>-<LAST3>-<NNNN>'}. {@code CITY3} is the upper-cased first three letters of the
283	     * city, {@code LAST3} the upper-cased first three letters of the last name, and {@code NNNN} a
284	     * per-city, 4-digit zero-padded sequence equal to one more than the number of owners already in
285	     * that city (e.g. {@code 'LON-SMI-0007'}).
286	     *
287	     * @param city the owner's city
288	     * @param lastName the owner's last name
289	     * @return the generated customer code
290	     */
291	    private String generateCustomerCode(String city, String lastName) {
292	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
293	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
294	        int sequence = (int) this.clinicService.findAllOwners().stream()
295	            .filter(existing -> equalsIgnoreCase(existing.getCity(), city))
296	            .count() + 1;
297	        return String.format("%s-%s-%04d", city3, last3, sequence);
298	    }
299	
300	    /**
301	     * Counts the existing owners that already share the given first name and last name, compared
302	     * case-insensitively. This is evaluated before the new owner is saved, so it reflects only the
303	     * owners that existed prior to this create.
304	     *
305	     * @param firstName the first name of the owner being created
306	     * @param lastName the last name of the owner being created
307	     * @return the number of pre-existing namesakes
308	     */
309	    private int countNamesakes(String firstName, String lastName) {
310	        return (int) this.clinicService.findAllOwners().stream()
311	            .filter(existing -> equalsIgnoreCase(existing.getFirstName(), firstName)
312	                && equalsIgnoreCase(existing.getLastName(), lastName))
313	            .count();
314	    }
315	
316	    /**
317	     * Compares two possibly-{@code null} strings for equality, ignoring case. Two {@code null} values
318	     * are considered equal and a {@code null} is never equal to a non-{@code null} value.
319	     *
320	     * @param a the first value, possibly {@code null}
321	     * @param b the second value, possibly {@code null}
322	     * @return whether the values are equal ignoring case
323	     */
324	    private boolean equalsIgnoreCase(String a, String b) {
325	        return a == null ? b == null : a.equalsIgnoreCase(b);
326	    }
327	
328	    /**
329	     * Rejects an owner payload that is missing or blank in any required field. Bean Validation
330	     * (via {@code @Valid}) already rejects {@code null} values and fields that violate their size
331	     * or pattern constraints; this guard additionally rejects whitespace-only values for fields
332	     * (such as address and city) that have no pattern constraint, so that no required field is blank.
333	     *
334	     * @param ownerFieldsDto the submitted owner fields
335	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
336	     */
337	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
338	        List<String> invalidFields = new ArrayList<>();
339	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
340	            invalidFields.add("firstName");
341	        }
342	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
343	            invalidFields.add("lastName");
344	        }
345	        if (!StringUtils.hasText(normalizeAddress(ownerFieldsDto.getAddress()))) {
346	            invalidFields.add("address");
347	        }
348	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
349	            invalidFields.add("city");
350	        }
351	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
352	            invalidFields.add("telephone");
353	        }
354	        if (!invalidFields.isEmpty()) {
355	            throw new InvalidOwnerFieldsException(invalidFields);
356	        }
357	    }
358	
359	    /**
360	     * Normalizes a submitted telephone number to E.164 form and requires the result to be valid. The
361	     * normalized E.164 string (a leading {@code '+'} followed by country code and national digits) is
362	     * what gets stored and returned.
363	     *
364	     * @param telephone the raw telephone value from the request
365	     * @return the normalized E.164 telephone number
366	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
367	     */
368	    private String normalizeTelephone(String telephone) {
369	        String e164 = toE164(telephone);
370	        if (e164 == null) {
371	            throw new InvalidOwnerFieldsException(List.of("telephone"));
372	        }
373	        return e164;
374	    }
375	
376	    /**
377	     * Converts a telephone value to E.164 form, giving the single authoritative definition of a
378	     * telephone's normalized form. Spaces, dashes and brackets are stripped. A leading {@code '+'}
379	     * and its country code are kept when present; otherwise country code {@code '+61'} is assumed and
380	     * a single leading {@code '0'} is dropped from the national digits. The result is valid only when
381	     * it contains 8 to 15 digits after the {@code '+'} and, for a recognized country code (see
382	     * {@link #NATIONAL_NUMBER_LENGTH}), carries exactly that country's required national-number length.
383	     *
384	     * <p>Returns {@code null} rather than throwing when the value cannot form a valid E.164 number, so
385	     * it is safe to apply to already-stored (possibly legacy) values when comparing them.
386	     *
387	     * @param telephone the raw telephone value, possibly {@code null}
388	     * @return the E.164 string, or {@code null} if the value cannot form a valid E.164 number
389	     */
390	    private String toE164(String telephone) {
391	        if (telephone == null) {
392	            return null;
393	        }
394	        String cleaned = telephone.replaceAll("[ \\-()]", "");
395	        String digits;
396	        if (cleaned.startsWith("+")) {
397	            digits = cleaned.substring(1);
398	        } else {
399	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
400	            digits = "61" + national;
401	        }
402	        if (!digits.matches("[0-9]{8,15}")) {
403	            return null;
404	        }
405	        if (!nationalNumberLengthValid(digits)) {
406	            return null;
407	        }
408	        return "+" + digits;
409	    }
410	
411	    /**
412	     * Checks a normalized E.164 digit string (country code followed by national digits, without the
413	     * leading {@code '+'}) against the per-country national-number length rule. For a country code
414	     * listed in {@link #NATIONAL_NUMBER_LENGTH} the national part must have exactly the required length
415	     * (e.g. {@code '+61'} needs 9 national digits, {@code '+1'} needs 10); any other country code is
416	     * accepted, leaving only the generic total-length rule to apply.
417	     *
418	     * @param digits the E.164 digits without the leading {@code '+'}
419	     * @return {@code true} if the national-number length matches the country code's requirement
420	     */
421	    private boolean nationalNumberLengthValid(String digits) {
422	        for (Map.Entry<String, Integer> entry : NATIONAL_NUMBER_LENGTH.entrySet()) {
423	            String code = entry.getKey();
424	            if (digits.startsWith(code)) {
425	                return digits.length() - code.length() == entry.getValue();
426	            }
427	        }
428	        return true;
429	    }
430	
431	    /**
432	     * Normalizes an optional owner email. An absent (null or blank) email is allowed and yields
433	     * {@code null}. When present, the value must be a syntactically valid address; it is then stored
434	     * and returned lower-cased.
435	     *
436	     * @param email the raw email value from the request, possibly {@code null}
437	     * @return the lower-cased email, or {@code null} when none was supplied
438	     * @throws InvalidOwnerFieldsException if a value is present but not a valid email address
439	     */
440	    private String normalizeEmail(String email) {
441	        if (!StringUtils.hasText(email)) {
442	            return null;
443	        }
444	        String trimmed = email.trim();
445	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
446	            throw new InvalidOwnerFieldsException(List.of("email"));
447	        }
448	        return trimmed.toLowerCase(Locale.ROOT);
449	    }
450	
451	    /**
452	     * Rejects an owner whose whole identity key is already used by an existing owner. This is the
453	     * single consolidated duplicate check: the identity key ({@link Owner#getIdentityKey()}) is the
454	     * owner's normalized telephone, email (empty when absent) and household id joined with
455	     * {@code '|'}, and a create is a duplicate only when the new owner's whole key equals an existing
456	     * owner's. Because the telephone is part of the key, two members of the same household
457	     * (same {@code householdId}) with different telephones have different identity keys and are both
458	     * allowed.
459	     *
460	     * @param owner the owner being created, with its normalized telephone, email and household id set
461	     * @throws DuplicateIdentityException if another owner already has this identity key
462	     */
463	    private void requireUniqueIdentity(Owner owner) {
464	        String identityKey = owner.getIdentityKey();
465	        boolean inUse = this.clinicService.findAllOwners().stream()
466	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
467	        if (inUse) {
468	            throw new DuplicateIdentityException(identityKey);
469	        }
470	    }
471	
472	    /**
473	     * Returns the existing owners that belong to the same household as the given last name and
474	     * address, i.e. those whose last name and address match case-insensitively and with runs of
475	     * whitespace collapsed to a single space.
476	     *
477	     * @param lastName the last name to match
478	     * @param address the address to match
479	     * @return the matching owners (possibly empty, never {@code null})
480	     */
481	    private List<Owner> findHouseholdMembers(String lastName, String address) {
482	        String normalizedLastName = normalizeForHousehold(lastName);
483	        String normalizedAddress = normalizeAddress(address);
484	        return this.clinicService.findAllOwners().stream()
485	            .filter(existing -> normalizeForHousehold(existing.getLastName()).equals(normalizedLastName)
486	                && normalizeAddress(existing.getAddress()).equals(normalizedAddress))
487	            .toList();
488	    }
489	
490	    /**
491	     * Joins the owner being created to the shared household of any existing owner(s) that have the
492	     * same last name and address (compared case-insensitively with collapsed whitespace). Every
493	     * member of the household - the existing owners and the new one - is assigned the same stable
494	     * {@code householdId}, so the shared identifier can be read back from any of them.
495	     *
496	     * <p>When no existing owner shares the household there is nobody to share an identifier with, so
497	     * the owner is left without a {@code householdId}.
498	     *
499	     * <p>Every member of the household - the existing owners and the new one - is also stamped with
500	     * the household's member count after this create ({@code householdSize}), so the shared size can
501	     * be read back from any of them.
502	     *
503	     * @param owner the owner being created, whose {@code householdId} is set when a household is joined
504	     */
505	    private void joinHousehold(Owner owner) {
506	        List<Owner> members = findHouseholdMembers(owner.getLastName(), owner.getAddress());
507	        if (members.isEmpty()) {
508	            return;
509	        }
510	        String householdId = computeHouseholdId(owner.getLastName(), owner.getAddress());
511	        int householdSize = members.size() + 1;
512	        owner.setHouseholdId(householdId);
513	        owner.setHouseholdSize(householdSize);
514	        for (Owner member : members) {
515	            member.setHouseholdId(householdId);
516	            member.setHouseholdSize(householdSize);
517	            this.clinicService.saveOwner(member);
518	        }
519	    }
520	
521	    /**
522	     * Computes the stable, shared household identifier for a last name and address. The value is
523	     * derived deterministically from the normalized (case-insensitive, whitespace-collapsed) last
524	     * name and address, so every owner in the same household computes the same identifier.
525	     *
526	     * @param lastName the last name of the household
527	     * @param address the address of the household
528	     * @return the household identifier, formatted {@code 'HH-<12 upper-case hex digits>'}
529	     */
530	    private String computeHouseholdId(String lastName, String address) {
531	        String key = normalizeForHousehold(lastName) + "\n" + normalizeAddress(address);
532	        try {
533	            byte[] digest = MessageDigest.getInstance("SHA-256")
534	                .digest(key.getBytes(StandardCharsets.UTF_8));
535	            StringBuilder hex = new StringBuilder();
536	            for (int i = 0; i < 6; i++) {
537	                hex.append(String.format("%02X", digest[i]));
538	            }
539	            return "HH-" + hex;
540	        } catch (NoSuchAlgorithmException e) {
541	            throw new IllegalStateException("SHA-256 algorithm not available", e);
542	        }
543	    }
544	
545	    /**
546	     * Normalizes a value for case-insensitive, whitespace-collapsed household comparison: leading and
547	     * trailing whitespace is trimmed, any internal run of whitespace is collapsed to a single space,
548	     * and the result is lower-cased. A {@code null} value normalizes to an empty string.
549	     *
550	     * @param value the raw value, possibly {@code null}
551	     * @return the normalized value
552	     */
553	    private String normalizeForHousehold(String value) {
554	        return collapseWhitespace(value).toLowerCase(Locale.ROOT);
555	    }
556	
557	    /**
558	     * Trims leading and trailing whitespace and collapses any internal run of whitespace to a single
559	     * space, giving the single definition of that step shared by the owner normalizers. A {@code null}
560	     * value yields an empty string.
561	     *
562	     * @param value the raw value, possibly {@code null}
563	     * @return the trimmed, whitespace-collapsed value
564	     */
565	    private String collapseWhitespace(String value) {
566	        if (value == null) {
567	            return "";
568	        }
569	        return value.trim().replaceAll("\\s+", " ");
570	    }
571	
572	    /**
573	     * Normalizes an owner's address to its canonical, stored-and-returned form: leading and trailing
574	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the result
575	     * is upper-cased, and common street-type abbreviations are expanded as whole words
576	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
577	     * blank-after-collapsing value normalizes to an empty string. The transformation is idempotent, so
578	     * applying it to an already-normalized (or legacy) value is safe when comparing addresses.
579	     *
580	     * @param address the raw address value, possibly {@code null}
581	     * @return the normalized address
582	     */
583	    private String normalizeAddress(String address) {
584	        String collapsed = collapseWhitespace(address).toUpperCase(Locale.ROOT);
585	        if (collapsed.isEmpty()) {
586	            return "";
587	        }
588	        String[] tokens = collapsed.split(" ");
589	        StringBuilder normalized = new StringBuilder();
590	        for (int i = 0; i < tokens.length; i++) {
591	            if (i > 0) {
592	                normalized.append(' ');
593	            }
594	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
595	        }
596	        return normalized.toString();
597	    }
598	
599	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
600	    @Override
601	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
602	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
603	        if (currentOwner == null) {
604	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
605	        }
606	        currentOwner.setAddress(ownerFieldsDto.getAddress());
607	        currentOwner.setCity(ownerFieldsDto.getCity());
608	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
609	        currentOwner.setLastName(ownerFieldsDto.getLastName());
610	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
611	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
612	        this.clinicService.saveOwner(currentOwner);
613	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
614	    }
615	
616	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
617	    @Transactional
618	    @Override
619	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
620	        Owner owner = this.clinicService.findOwnerById(ownerId);
621	        if (owner == null) {
622	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
623	        }
624	        this.clinicService.deleteOwner(owner);
625	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
626	    }
627	
628	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
629	    @Override
630	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
631	        Owner owner = this.clinicService.findOwnerById(ownerId);
632	        if (owner == null) {
633	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
634	        }
635	        HttpHeaders headers = new HttpHeaders();
636	        Pet pet = petMapper.toPet(petFieldsDto);
637	        owner.setId(ownerId);
638	        pet.setOwner(owner);
639	        pet.getType().setName(null);
640	        this.clinicService.savePet(pet);
641	        PetDto petDto = petMapper.toPetDto(pet);
642	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
643	            .buildAndExpand(pet.getId()).toUri());
644	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
645	    }
646	
647	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
648	    @Override
649	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
650	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
651	        if (currentOwner != null) {
652	            Pet currentPet = this.clinicService.findPetById(petId);
653	            if (currentPet != null) {
654	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
655	                currentPet.setName(petFieldsDto.getName());
656	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
657	                this.clinicService.savePet(currentPet);
658	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
659	            }
660	        }
661	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
662	    }
663	
664	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
665	    @Override
666	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
667	        HttpHeaders headers = new HttpHeaders();
668	        Visit visit = visitMapper.toVisit(visitFieldsDto);
669	        Pet pet = new Pet();
670	        pet.setId(petId);
671	        visit.setPet(pet);
672	        this.clinicService.saveVisit(visit);
673	        VisitDto visitDto = visitMapper.toVisitDto(visit);
674	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
675	            .buildAndExpand(visit.getId()).toUri());
676	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
677	    }
678	
679	
680	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
681	    @Override
682	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
683	        Owner owner = this.clinicService.findOwnerById(ownerId);
684	        if (owner != null) {
685	            Pet pet = owner.getPet(petId);
686	            if (pet != null) {
687	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
688	            }
689	        }
690	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
691	    }
692	}
